from taf.collectors.btslog.collector import BtslogCollector
from taf.collectors.core.factories.factory import Factory
from taf.collectors.core.templates.dynamic_class_creation import Creating
from taf.collectors.core.factories.named_factory import NamedComponentFactory

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class BtslogCollectorFactory(NamedComponentFactory):
    """
           Factory to create btslog collectors
    """
    _optional_parameters = {"btslog_path", "btslog_launcher_path", "log_dir", "target_file_name",
                            "poll_interval", "start_timeout", "teardown_timeout", "syslog_timeout",
                            "btslog_configuration"}
    _product_class = BtslogCollector


class RemoteBtslogCollectorFactory(Creating("tool_executor", "SshExecutor", "executor"),
                                   Creating("file_putter", "SshFilePutter", "executor"),
                                   Creating("file_getter", "SshFileGetter", "executor"),
                                   BtslogCollectorFactory):
    pass


class LocalBtslogCollectorFactory(Creating("tool_executor", "LocalExecutor"),
                                  Creating("file_putter", "LocalFilePutter"),
                                  Creating("file_getter", "LocalFileGetter"),
                                  BtslogCollectorFactory):
    pass


class BtslogCollectorFactorySelector(Factory):

    def create(self, configuration, existing_arguments):
        if "executor" in configuration:
            return RemoteBtslogCollectorFactory().create(configuration=configuration,
                                                         existing_arguments=existing_arguments)
        else:
            return LocalBtslogCollectorFactory().create(configuration=configuration,
                                                        existing_arguments=existing_arguments)
